#include "sio_uart_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

Boolean sio_uart_wait_tx_ready (Sio_Uart sio_uart , Sio_Timeout timeout)
{
  CRITICAL ;

  Boolean status ;

  os_timeout_arm_set ((TskTimeoutFunc) sio_uart_irq_tx_dis , sio_uart) ;
    {
      C_ENTER ;
        {
          sio_uart_irq_tx_ena  (sio_uart) ;

          status = os_irq_wait (sio_uart->tx.irq , TRUE , timeout) ;
        }
      C_LEAVE ;
    }
  os_timeout_arm_clr () ;

  return status ;
}

